// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.diimport timber.log.Timberimport com.roshan.persona.common.AudioDispatcherimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.voice.capture.AudioCapturePipelineimport com.roshan.persona.voice.capture.CircularAudioBufferimport com.roshan.persona.voice.conversation.ConversationEngineimport com.roshan.persona.voice.conversation.ConversationEventimport com.roshan.persona.voice.conversation.ConversationStateimport com.roshan.persona.voice.emotion.SpeechEmotionRecognizerimport com.roshan.persona.voice.emotion.UserEmotionimport com.roshan.persona.voice.stt.DeltaContextUpdaterimport com.roshan.persona.voice.stt.SttConfidenceScorerimport com.roshan.persona.voice.stt.SttResultimport com.roshan.persona.voice.stt.StreamingSttEngineimport com.roshan.persona.voice.tts.Emotionimport com.roshan.persona.voice.tts.EmotionalTtsEngineimport com.roshan.persona.voice.tts.VoicePersonaimport com.roshan.persona.voice.wakeword.WakeWordDetectorimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Jobimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.collectimport kotlinx.coroutines.launchimport kotlinx.coroutines.sync.Muteximport kotlinx.coroutines.sync.withLockimport kotlinx.coroutines.yieldimport javax.inject.Injectimport javax.inject.Singletonimport java.util.concurrent.atomic.AtomicReference/** * NOUS — Voice Facade (Step 5.14 — single entry point for Module 5). * * The one class that the Brain (Module 2) and UI (Module 6) talk to. * Everything else in :feature:voice is an implementation detail. * * ## Public API (4 methods + 1 state flow) * *  - [startListening]   — wake word detected (or tap-to-talk) → begin STT. *  - [stopListening]    — cancel STT mid-utterance. *  - [stopSpeaking]     — cancel TTS mid-response (user interrupted). *  - [changePersona]    — switch active voice persona (JARVIS → FRIDAY etc.). *  - [state]            — observe current voice state (IDLE/LISTENING/THINKING/SPEAKING). * * ## Internal pipeline * * ``` * WakeWord fires ─→ startListening() *     ↓ * AudioCapturePipeline starts (already running if always-on) *     ↓ * StreamingSttEngine.recognize(audioChunks) *     ↓ emits SttResult.Partial every 200ms * DeltaContextUpdater.processDelta(partial) → Brain gets incremental updates *     ↓ emits SttResult.Final on 500ms silence * SpeechEmotionRecognizer.recognize(audio) → user emotion (parallel) *     ↓ * VoiceBrainBridge.onUserUtterance(transcript, confidence, emotion, speakerId) *     ↓ * VoiceBrainBridge.produceResponse() → BrainResponse(text, emotion, persona) *     ↓ * EmotionalTtsEngine.speak(text, emotion, persona) *     ↓ TTS plays * BargeInDetector monitors mic — if user speaks → stopForBargeIn() *     ↓ TTS done * State returns to IDLE — ready for next wake word. * ``` * * ## State machine * * ``` * IDLE ──(startListening)──→ LISTENING ──(SttResult.Final)──→ THINKING *   ↑                                                          │ *   │                                                      (BrainResponse) *   │                                                          │ *   └────(TTS done)─────SPEAKING ←────(TTS starts)─────────────┘ * ``` * * ## Testability * * The facade depends on already-testable interfaces (StreamingSttEngine, * EmotionalTtsEngine, ConversationEngine, etc.). Tests inject fakes and * drive the state machine via the public API. The full integration test * (wake word → STT → Brain → TTS → barge-in) ships as an instrumentation * test in :app. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§24 Step 5.14 VoiceModule (Hilt) + wiring to brain</a> */@Singletonclass VoiceFacade @Inject constructor(    private val capturePipeline: AudioCapturePipeline,    private val streamingStt: StreamingSttEngine,    private val confidenceScorer: SttConfidenceScorer,    private val deltaUpdater: DeltaContextUpdater,    private val tts: EmotionalTtsEngine,    private val emotionRecognizer: SpeechEmotionRecognizer,    private val conversationEngine: ConversationEngine,    private val brainBridge: VoiceBrainBridge,    private val circularBuffer: CircularAudioBuffer,    @VoiceScope private val voiceScope: CoroutineScope,    @AudioDispatcher private val audioDispatcher: CoroutineDispatcher,) {    /** Active voice persona (mutable at runtime via [changePersona]). */    private val activePersona = AtomicReference(VoicePersona.ATLAS)    /** Current voice state — observe via [state]. */    private val _state = MutableStateFlow(VoiceState.IDLE)    val state: StateFlow<VoiceState> = _state.asStateFlow()    /** Mutex to serialize conversation turns (no overlap). */    private val turnMutex = Mutex()    /** Current STT collection job (null when not listening). */    private var sttJob: Job? = null    // ─── Public API ─────────────────────────────────────────────────────────    /**     * Begin listening for a user utterance.     *     * Called by the wake word detector (when "Hey NOUS" fires) or by the UI     * (tap-to-talk button). The facade transitions to LISTENING and starts     * the STT engine on the captured audio stream.     *     * Idempotent — calling twice is a no-op (returns false).     *     * @return true if listening started, false if already listening.     */    suspend fun startListening(): Boolean {        if (!turnMutex.tryLock()) {            Timber.tag(TAG).w("startListening called while a turn is in progress — ignoring.")            return false        }        try {            if (_state.value != VoiceState.IDLE) {                Timber.tag(TAG).w("startListening called in state ${_state.value} — ignoring.")                return false            }            _state.value = VoiceState.LISTENING            deltaUpdater.reset()            Timber.tag(TAG).i("VoiceFacade: LISTENING (persona=${activePersona.get()}).")            // Collect STT results on the voice scope.            sttJob = voiceScope.launch(audioDispatcher) {                try {                    val sttFlow = streamingStt.recognize(capturePipeline.chunks)                    sttFlow.collect { result ->                        when (result) {                            is SttResult.Partial -> handlePartial(result)                            is SttResult.Final -> handleFinal(result)                            is SttResult.Error -> handleError(result)                        }                    }                } catch (t: Throwable) {                    Timber.tag(TAG).e("STT collection failed", t)                    _state.value = VoiceState.IDLE                }            }            return true        } finally {            turnMutex.unlock()        }    }    /** Cancel STT mid-utterance. Returns to IDLE. */    fun stopListening() {        sttJob?.cancel()        sttJob = null        if (_state.value == VoiceState.LISTENING) {            _state.value = VoiceState.IDLE            Timber.tag(TAG).i("VoiceFacade: stopListening → IDLE.")        }    }    /** Stop TTS immediately (user interrupted or navigated away). */    fun stopSpeaking() {        tts.stop()        if (_state.value == VoiceState.SPEAKING) {            _state.value = VoiceState.IDLE            Timber.tag(TAG).i("VoiceFacade: stopSpeaking → IDLE.")        }    }    /**     * Switch the active voice persona at runtime.     *     * Takes effect on the next TTS call. If NOUS is currently speaking,     * the current utterance finishes in the old persona.     */    fun changePersona(persona: VoicePersona) {        val old = activePersona.getAndSet(persona)        if (old != persona) {            Timber.tag(TAG).i("VoiceFacade: persona changed $old → $persona.")        }    }    /** Get the currently active persona. */    fun activePersona(): VoicePersona = activePersona.get()    // ─── Internal handlers ──────────────────────────────────────────────────    private suspend fun handlePartial(partial: SttResult.Partial) {        // Forward delta to the Brain via the bridge (incremental context update).        val delta = deltaUpdater.processDelta(partial.text) ?: return        // Brain doesn't process partials (only finals), but we could notify it        // for "instant start" optimization in a future revision.        Timber.tag(TAG).v("STT partial delta: ${delta.type} '${delta.newWords}'.")    }    private suspend fun handleFinal(final: SttResult.Final) {        _state.value = VoiceState.THINKING        Timber.tag(TAG).i("VoiceFacade: THINKING (transcript='${final.text}', conf=${final.confidence}).")        // Cancel STT collection — we have the final.        sttJob?.cancel()        sttJob = null        // 1. Detect user emotion (parallel with brain processing).        val audio = circularBuffer.snapshot()        val emotion = if (audio.isNotEmpty()) {            runCatching { emotionRecognizer.recognize(audio) }                .onFailure { Timber.tag(TAG).w("Emotion recognition failed", it) }                .getOrDefault(UserEmotion.UNKNOWN)        } else UserEmotion.UNKNOWN        // 2. Notify Brain.        val correlationId = CorrelationId.generate()        runCatching {            brainBridge.onUserUtterance(                transcript = final.text,                confidence = final.confidence,                emotion = emotion,                speakerId = null,  // wired when speaker recognition is in-line                correlationId = correlationId,            )        }.onFailure { Timber.tag(TAG).w("Brain bridge onUserUtterance failed", it) }        // 3. Ask Brain for a response.        val response = runCatching { brainBridge.produceResponse(correlationId) }            .onFailure { Timber.tag(TAG).w("Brain bridge produceResponse failed", it) }            .getOrNull()        if (response == null) {            Timber.tag(TAG).w("Brain returned no response — returning to IDLE.")            _state.value = VoiceState.IDLE            return        }        // 4. Speak the response.        speakResponse(response)    }    private suspend fun handleError(error: SttResult.Error) {        Timber.tag(TAG).w("STT error: ${error.reason} — ${error.message}.")        sttJob?.cancel()        sttJob = null        _state.value = VoiceState.IDLE    }    private suspend fun speakResponse(response: BrainResponse) {        // Apply the persona from the response, or fall back to the active one.        val persona = response.persona        activePersona.set(persona)        _state.value = VoiceState.SPEAKING        Timber.tag(TAG).i("VoiceFacade: SPEAKING (persona=$persona, emotion=${response.emotion}).")        tts.speak(            text = response.text,            emotion = response.emotion,            persona = persona,            onDone = {                _state.value = VoiceState.IDLE                Timber.tag(TAG).i("VoiceFacade: TTS done → IDLE.")            },            onBargeIn = {                _state.value = VoiceState.IDLE                Timber.tag(TAG).i("VoiceFacade: TTS barged-in → IDLE.")            },        )        yield()    }    private companion object {        private const val TAG = "VoiceFacade"    }}// ──────────────────────────────────────────────────────────────────────────/** Top-level voice state — observed by UI (Module 6) for voice orb animation. */enum class VoiceState {    /** Not listening, not speaking. Wake word detector (if active) is running. */    IDLE,    /** Listening to user speech via STT. */    LISTENING,    /** STT final received; Brain is processing the utterance. */    THINKING,    /** NOUS is speaking via TTS. */    SPEAKING,}